// ============================================================
//  Пульт тепловизора: ESP32 DevKit + веб-интерфейс (тёмный)
//  Точка доступа: SSID "CamCtrl", пароль "12345678"
//  Адрес: http://192.168.4.1
//  UART2: RX=16 (сюда TX камеры), TX=17 (сюда RX камеры), GND общий
//
//  Команды: isp reg_usr luma N, ctr N, enh N
//  При старте: автоотправка luma 50 и ctr 50 (enh не трогаем!)
//  Шаг: luma/ctr — 5, enh — 50
//  Значения живут в памяти ESP32 до её перезагрузки
//  Полный лог: всё, что камера печатает в UART, попадает в лог
//  Калибровка: isp auto_cut_off / isp auto_cut_on (шторка)
//  Антитуман: страховочный таймер — isp cut каждые CUT_PERIOD минут
//  OTA: обновление прошивки через веб-страницу (файл .bin)
// ============================================================

#include <WiFi.h>
#include <WebServer.h>
#include <Update.h>

const char* AP_SSID = "CamCtrl";
const char* AP_PASS = "12345678";   // минимум 8 символов

// Команды автокалибровки (проверены камерой)
const char* CMD_CALIB_OFF = "isp auto_cut_off";  // отключить автокалибровку шторкой
const char* CMD_CALIB_ON  = "isp auto_cut_on";   // включить обратно
const char* CMD_CUT_NOW   = "isp cut";           // принудительная калибровка сейчас

// ---------- антитуман: страховочный таймер ----------
const unsigned long CUT_PERIOD = 180000UL;  // период принудительной калибровки, мс (3 мин)
const int CUT_PERIOD_MIN = CUT_PERIOD / 60000;
bool cutTimerEnabled = true;
unsigned long lastCut = 0;

HardwareSerial Cam(2);
WebServer server(80);

int luma = 50;            // при каждой загрузке ESP32 снова 50
int ctr  = 50;
int enh  = 0;             // при загрузке ESP32 отображается 0 — реальное значение живёт в камере
const int STEP_LC  = 5;   // шаг яркости/контраста
const int STEP_ENH = 50;  // шаг резкости
const int MAX_ENH  = 1000; // максимум по тесту; если камера приняла больше — поправь здесь

bool calibEnabled = true;

// ---------- лог ----------
#define LOG_LINES 200
String logs[LOG_LINES];
int logIdx = 0;

void addLog(const String& s) {
  logs[logIdx] = s;
  logIdx = (logIdx + 1) % LOG_LINES;
}

String getLogs() {
  String out = "";
  for (int i = 0; i < LOG_LINES; i++) {
    int idx = (logIdx + i) % LOG_LINES;
    if (logs[idx].length()) {
      out += logs[idx];
      out += "\n";
    }
  }
  return out;
}

// ---------- экранирование для JSON ----------
String jsonEscape(String s) {
  s.replace("\\", "\\\\");
  s.replace("\"", "\\\"");
  s.replace("\n", "\\n");
  s.replace("\r", "");
  return s;
}

// ---------- фоновое чтение UART камеры ----------
String camLine = "";
unsigned long lastByte = 0;

void pollCam() {
  while (Cam.available()) {
    char c = (char)Cam.read();
    lastByte = millis();
    if (c == '\n') {
      camLine.trim();
      if (camLine.length()) addLog("[CAM] " + camLine);
      camLine = "";
    }
    else if (c != '\r') {
      camLine += c;
    }
  }
  // если камера напечатала что-то без перевода строки — сбрасываем по тишине
  if (camLine.length() && millis() - lastByte > 3000) {
    camLine.trim();
    if (camLine.length()) addLog("[CAM] " + camLine);
    camLine = "";
  }
}

// ---------- отправка команды камере ----------
void camCmd(const String& cmd) {
  addLog("[ESP] " + cmd);
  Cam.print(cmd);
  Cam.print("\r\n");
  // ответ придёт фоново через pollCam()
}

// ---------- перезагрузка камеры ----------
void camReboot() {
  camCmd("reboot");   // если у камеры другое имя команды — поправь здесь
}

// ---------- автокалибровка камеры ----------
void calibToggle() {
  if (calibEnabled) {
    camCmd(CMD_CALIB_OFF);
    addLog("[ESP] Автокалибровка шторкой отключена");
  } else {
    camCmd(CMD_CALIB_ON);
    addLog("[ESP] Автокалибровка шторкой включена");
  }
  calibEnabled = !calibEnabled;
}

// ---------- страховочный таймер калибровки ----------
void cutTimerToggle() {
  cutTimerEnabled = !cutTimerEnabled;
  lastCut = millis();  // чтобы после включения не щёлкнуло сразу
  if (cutTimerEnabled)
    addLog("[ESP] Таймер калибровки ВКЛ (каждые " + String(CUT_PERIOD_MIN) + " мин)");
  else
    addLog("[ESP] Таймер калибровки ВЫКЛ");
}

void checkCutTimer() {
  if (!cutTimerEnabled) return;
  if (millis() - lastCut >= CUT_PERIOD) {
    lastCut = millis();
    addLog("[ESP] Плановая калибровка (таймер " + String(CUT_PERIOD_MIN) + " мин)");
    camCmd(CMD_CUT_NOW);
  }
}

// ---------- веб-страница ----------
const char PAGE[] PROGMEM = R"rawliteral(
