// ---------- обработчики сервера ----------
void handleRoot() {
  server.send_P(200, "text/html", PAGE);
}

// ---------- OTA: приём файла прошивки ----------
void handleOtaUpload() {
  HTTPUpload& upload = server.upload();

  if (upload.status == UPLOAD_FILE_START) {
    addLog("[OTA] Начало загрузки: " + upload.filename);
    if (!Update.begin(UPDATE_SIZE_UNKNOWN, U_FLASH)) {
      addLog("[OTA] Ошибка begin: " + String(Update.errorString()));
    }
  }
  else if (upload.status == UPLOAD_FILE_WRITE) {
    if (Update.write(upload.buf, upload.currentSize) != upload.currentSize) {
      addLog("[OTA] Ошибка записи: " + String(Update.errorString()));
    }
  }
  else if (upload.status == UPLOAD_FILE_END) {
    if (Update.end(true)) {
      addLog("[OTA] Прошивка принята: " + String(Update.size() / 1024) + " КБ. Перезагрузка...");
      server.sendHeader("Connection", "close");
      server.send(200, "text/plain", "OK — модуль перезагружается, подключитесь к Wi-Fi заново");
      delay(500);
      ESP.restart();
    } else {
      addLog("[OTA] Ошибка end: " + String(Update.errorString()));
      server.send(500, "text/plain", "Ошибка прошивки — см. лог");
    }
  }
  else if (upload.status == UPLOAD_FILE_ABORTED) {
    Update.end();
    addLog("[OTA] Загрузка прервана");
  }
}

void handleCmd() {
  String p = server.arg("param");
  String d = server.arg("dir");

  if (p == "luma") {
    if      (d == "up")   luma += STEP_LC;
    else if (d == "down") luma -= STEP_LC;
    if (luma < 0)   luma = 0;
    if (luma > 100) luma = 100;
    camCmd("isp reg_usr luma " + String(luma));
  }
  else if (p == "ctr") {
    if      (d == "up")   ctr += STEP_LC;
    else if (d == "down") ctr -= STEP_LC;
    if (ctr < 0)   ctr = 0;
    if (ctr > 100) ctr = 100;
    camCmd("isp reg_usr ctr " + String(ctr));
  }
  else if (p == "enh") {
    if      (d == "up")   enh += STEP_ENH;
    else if (d == "down") enh -= STEP_ENH;
    if (enh < 0)      enh = 0;
    if (enh > MAX_ENH) enh = MAX_ENH;
    camCmd("isp reg_usr enh " + String(enh));
  }
  else if (p == "save")   camCmd("isp reg2cfg 0");
  else if (p == "reboot") camReboot();
  else if (p == "calib")  calibToggle();
  else if (p == "cutnow") { addLog("[ESP] Ручная калибровка"); camCmd(CMD_CUT_NOW); }
  else if (p == "timer")  cutTimerToggle();

  String out = "{\"luma\":" + String(luma) +
               ",\"ctr\":" + String(ctr) +
               ",\"enh\":" + String(enh) +
               ",\"calib\":" + String(calibEnabled ? "true" : "false") +
               ",\"timer\":" + String(cutTimerEnabled ? "true" : "false") +
               ",\"log\":\"" + jsonEscape(getLogs()) + "\"}";
  server.send(200, "application/json", out);
}

void handlePoll() {
  String out = "{\"calib\":" + String(calibEnabled ? "true" : "false") +
               ",\"timer\":" + String(cutTimerEnabled ? "true" : "false") +
               ",\"log\":\"" + jsonEscape(getLogs()) + "\"}";
  server.send(200, "application/json", out);
}

// ---------- инициализация ----------
void setup() {
  Serial.begin(115200);

  Cam.begin(115200, SERIAL_8N1, 16, 17);  // RX=16, TX=17

  WiFi.mode(WIFI_AP);
  WiFi.softAP(AP_SSID, AP_PASS);
  addLog("[ESP] AP запущена: " + String(AP_SSID));
  addLog("[ESP] IP: " + WiFi.softAPIP().toString());

  server.on("/", handleRoot);
  server.on("/cmd", handleCmd);
  server.on("/poll", handlePoll);
  server.on("/update", HTTP_POST, []() {
    // сюда попадаем, только если UPLOAD_FILE_END не сработал
    server.send(500, "text/plain", "Ошибка прошивки");
  }, handleOtaUpload);
  server.begin();

  // при загрузке подкидываем камере стартовые значения по очереди
  camCmd("isp reg_usr luma 50");
  camCmd("isp reg_usr ctr 50");
  // enh при старте НЕ отправляем: у камеры может быть своё сохранённое
  // значение (reg2cfg), не хотим его перетирать нулём

  // включаем родную автокалибровку камеры и сохраняем в её конфиг,
  // чтобы настройка пережила выключение питания камеры
  camCmd(CMD_CALIB_ON);
  camCmd("isp reg2cfg 0");
  addLog("[ESP] Автокалибровка включена и сохранена в конфиг камеры");

  lastCut = millis();
}

void loop() {
  pollCam();          // непрерывно читаем камеру — весь её вывод в лог
  checkCutTimer();    // страховочная калибровка по таймеру
  server.handleClient();
}
